def brackets_balanced(s: str) -> bool:
    pairs = {')': '(', ']': '[', '}': '{'}
    opens = set(pairs.values())
    stack = []
    i = 0
    n = len(s)
    in_string = False
    while i < n:
        c = s[i]
        if in_string:
            if c == '\\':
                i += 2
                continue
            elif c == '"':
                in_string = False
            i += 1
            continue
        else:
            if c == '"':
                in_string = True
                i += 1
                continue
            elif c in opens:
                stack.append(c)
            elif c in pairs:
                if not stack or stack[-1] != pairs[c]:
                    return False
                stack.pop()
            i += 1
    if in_string:
        return False
    return not stack
